 stage="cash debit and replay";auto bought=shop.buy("premium-fixture",eid,600,1,1,"premium-fixture-buy");auto balance=shop.balance("premium-fixture");check(balance==999995&&inv.items(eid).at(0).item==500999997,"Cash not debited or coin not granted");check(shop.buy("premium-fixture",eid,600,1,1,"premium-fixture-buy")==bought&&shop.balance("premium-fixture")==balance,"Purchase replay debited twice");
 reject([&]{shop.buy("premium-fixture",other,600,1,1,"premium-fixture-buy");},"Receipt crossed characters");check(inv.items(other).empty(),"Item leaked to other character");reject([&]{shop.buy("premium-fixture",eid,600,3,2,"premium-fixture-coincap");},"Coin purchase cap absent");reject([&]{shop.buy("premium-fixture",eid,600,1,0,"premium-fixture-zero");},"Zero quantity accepted");reject([&]{shop.buy("no-wallet",other,600,1,1,"premium-fixture-poor");},"Insufficient wallet accepted");check(shop.history("premium-fixture").at("rows").size()==1&&shop.history("other-account").at("rows").empty(),"History crossed accounts");
 stage="class and duration";int timed=0,permanent=0,wrong=0;auto rules=content.get("data/native_item_rules.json");
 for(auto&a:catalog.at("offers")){if(a.value("unavailable",false))continue;if(a.value("class",600)!=600){if(!wrong&&a.at("section")==6&&a.at("items").size()==4&&a.value("purchase_mode",std::string())=="direct")wrong=a.at("id");continue;}for(auto&i:a.at("items")){auto&r=rules.at(std::to_string(i[0].get<std::uint32_t>()));if((r.at("kind")==1||r.at("kind")==11)&&r.value("duration",0)>0&&!timed)timed=a.at("id");if(r.at("kind")==1&&r.value("duration",0)==0&&!permanent)permanent=a.at("id");}}
 check(timed&&permanent&&wrong,"Missing duration/class coverage");shop.buy("premium-fixture",78005,600,wrong,1,"premium-fixture-class");check(inv.items(78005).size()==4,"Other-class gift did not deliver four pieces");shop.buy("premium-fixture",other,600,timed,1,"premium-fixture-timed");bool expiry=false;for(auto&i:inv.items(other))expiry=expiry||bool(i.expires);check(expiry,"Rental made permanent");
 stage="full bag rollback";constexpr std::uint32_t full=78003;for(int i=0;i<20;i++)inv.grant_once(full,{{1001,1}},"premium-fixture-full-"+std::to_string(i));balance=shop.balance("premium-fixture");reject([&]{shop.buy("premium-fixture",full,600,permanent,1,"premium-fixture-full-buy");},"Full inventory accepted purchase");check(shop.balance("premium-fixture")==balance,"Failed delivery charged Cash");

 stage="catalog choice boxes";
 for(int cls:{100,200,300,400,500,600,800}){
  Json offer;for(auto&a:catalog.at("offers"))if(a.value("class",0)==cls&&a.value("purchase_mode",std::string())=="boxed"&&rules.at(std::to_string(a["choice_targets"][0][0].get<std::uint32_t>())).value("duration",0)==0){offer=a;break;}
  check(!offer.is_null(),"Class has no permanent boxed costume");auto owner=std::uint32_t(800000+cls);auto event="class-boxes-"+std::to_string(cls);shop.buy("premium-fixture",owner,cls,offer.at("id"),1,event);auto paid=shop.balance("premium-fixture");auto selectors=inv.items(owner);check(selectors.size()==4,"Boxed costume did not deliver exactly four selectors");CashChoices choices(db,content,inv);
  for(auto&selector:selectors){check(selector.item>=1000900000&&selector.item<1000900028,"Non-selector delivered in box mode");auto preview=choices.preview(owner,selector.uid,cls);check(preview.at("options").size()==2,"Shop box lost exclusive options");reject([&]{choices.choose(owner+1,selector.uid,cls,1);},"Box chosen by another character");auto result=choices.choose(owner,selector.uid,cls,1);check(choices.choose(owner,selector.uid,cls,1)==result,"Catalog box replay duplicated target");reject([&]{choices.choose(owner,selector.uid,cls,2);},"Catalog box delivered both options");bool correct=false;for(auto&i:offer.at("choice_targets"))correct=correct||i[0]==result.at("item");check(correct,"Catalog box delivered Santa instead of purchased costume");}
  auto gear=inv.items(owner);check(gear.size()==4&&std::all_of(gear.begin(),gear.end(),[](auto&i){return !i.expires;}),"Permanent boxed costume became rental or duplicated");shop.buy("premium-fixture",owner,cls,offer.at("id"),1,event);check(inv.items(owner).size()==4&&shop.balance("premium-fixture")==paid,"Order replay delivered boxes twice");
 }
 Json rental;for(auto&a:catalog.at("offers"))if(a.value("class",0)==600&&a.value("purchase_mode",std::string())=="boxed"&&rules.at(std::to_string(a["choice_targets"][0][0].get<std::uint32_t>())).value("duration",0)>0){rental=a;break;}check(!rental.is_null(),"Missing timed boxed costume");constexpr std::uint32_t timedOwner=810600;shop.buy("premium-fixture",timedOwner,600,rental.at("id"),1,"rental-boxes");auto first=inv.items(timedOwner).at(0);auto deadline=std::int64_t(now()+120);db.exec("UPDATE reward_instances SET expires_at=? WHERE uid=?",{deadline,std::int64_t(first.uid)});CashChoices timedChoices(db,content,inv);auto chosen=timedChoices.choose(timedOwner,first.uid,600,2);bool preserved=false;for(auto&i:inv.items(timedOwner))if(i.uid==chosen.at("uid"))preserved=i.expires&&*i.expires==deadline;check(preserved,"Catalog box renewed or lost original rental deadline");
 auto beforeFailed=shop.balance("premium-fixture");reject([&]{shop.buy("premium-fixture",full,600,rental.at("id"),1,"boxed-overflow");},"Full bag accepted boxed costume");check(shop.balance("premium-fixture")==beforeFailed&&db.query("SELECT 1 FROM native_cash_piece_boxes WHERE eid=?",{std::int64_t(full)}).empty(),"Failed boxed delivery charged Cash or left payload");
 auto pages=shop.state("premium-fixture",600);std::size_t boxedCount=0;for(auto&page:pages)if(page.value("cmd",std::string())=="shop.articles"){check(page.dump().size()<60000,"Shop page exceeds native message bound");for(auto&a:page.at("articles")){check(a.size()==9&&a[8].contains("class")&&a[8].contains("level"),"Shop class/level metadata missing");boxedCount+=a[8].value("mode",std::string())=="boxed";}}check(boxedCount>1000,"Class-level catalog omitted boxed outfits");
 stage="Python wire parity";auto parity=Json::parse(read_file(argv[2]));for(auto&r:parity.at("rows")){auto req=unhex(r.at("request"));check(shop.machines(req)==unhex(r.at("machines")),"Machine wire diverges from Python");check(shop.prizes(req)==unhex(r.at("prizes")),"Prize wire diverges from Python");}reject([&]{shop.prizes(Bytes(7));},"Malformed gacha list accepted");
 stage="spin ownership and replay";auto coin=inv.items(eid).at(0);auto address=Inventory::address(coin.slot);Bytes spin(24);put16(spin,0,1,true);put32(spin,2,1,true);put32(spin,6,address.first,true);put32(spin,10,address.second,true);put16(spin,22,606,true);reject([&]{shop.spin("premium-fixture",other,spin,"premium-fixture-foreign");},"Gacha debited another character coin");auto reply=shop.spin("premium-fixture",eid,spin,"premium-fixture-spin",[](auto){return 0;});check(get32(reply,14,true)==999000303,"Wrong deterministic reward");check(shop.spin("premium-fixture",eid,spin,"premium-fixture-spin")==reply,"Gacha replay rerolled");int rewards=0,coins=0;for(auto&i:inv.items(eid)){if(i.item==999000303)rewards+=i.quantity;if(i.item==500999997)coins+=i.quantity;}check(rewards==1&&coins==0,"Gacha duplicated prize or coin");reject([&]{shop.spin("premium-fixture",eid,spin,"premium-fixture-spin-again");},"Gacha without coin accepted");
 stage="gacha rollback on full inventory";constexpr std::uint32_t packed=78004;for(int i=0;i<19;i++)inv.grant_once(packed,{{1001,1}},"premium-packed-"+std::to_string(i));inv.grant_once(packed,{{500999997,2}},"premium-packed-coins");auto packedCoin=inv.items(packed).back();check(packedCoin.item==500999997,"Fixture coin slot changed");auto packedAddress=Inventory::address(packedCoin.slot);auto packedSpin=spin;put32(packedSpin,6,packedAddress.first,true);put32(packedSpin,10,packedAddress.second,true);reject([&]{shop.spin("premium-fixture",packed,packedSpin,"premium-packed-spin",[](auto){return 0;});},"Full inventory accepted gacha prize");check(inv.items(packed).back().quantity==2&&db.query("SELECT 1 FROM local_item_orders WHERE event_key='premium-packed-spin'").empty(),"Failed gacha lost coin or recorded reward");
 stage="price refresh after catalog edit";
