 db.exec("DELETE FROM cash_price_edits WHERE offer=1");
 stage="world UI integration";Progression progression;Json character={{"eid",79001},{"name","PremiumFixture"},{"cls",600},{"level",115},{"exp",progression.threshold(115)},{"hp",100000},{"mp",100000}};db.exec("INSERT INTO accounts(id,payload) VALUES(?,?)",{std::string("premium-fixture"),Json{{"chars",Json::array({character})}}.dump()});Session session;session.identity.id="premium-fixture";session.id=token(20);session.channel=1;session.expires=now()+600;
 struct Packet{int cat,sub;Bytes body;};std::vector<Packet>packets;auto send=[&](unsigned char c,unsigned char s,const Bytes&b){packets.push_back({c,s,b});};WorldSession game(content,store,session,root,79001);Bytes ready(21);put32(ready,1,79001,true);putfloat(ready,5,9020);putfloat(ready,9,6590);putfloat(ready,13,627);game.handle(4,0,ready,send);packets.clear();auto command=[&](std::string text,std::string event){Bytes b(text.begin(),text.end());b.push_back(0);check(game.handle(7,1,b,send,event),"Shop command not handled");};command("//cashshop","premium-ui-in-game-button");
